I've written this in Python with `smtplib`, since you didn't specify a language. The cap is enforced with a semaphore, so it holds under concurrency.

```python
import smtplib
import ssl
import threading
import time
from collections import deque
from contextlib import contextmanager


class PoolTimeout(Exception):
    """No connection became available within acquire_timeout."""


class _PooledConn:
    __slots__ = ("smtp", "created", "last_used", "sent")

    def __init__(self, smtp):
        self.smtp = smtp
        self.created = self.last_used = time.monotonic()
        self.sent = 0


class SMTPPool:
    def __init__(
        self,
        host,
        port=587,
        username=None,
        password=None,
        *,
        max_size=40,
        use_starttls=True,
        connect_timeout=10,
        acquire_timeout=30,
        idle_check_after=30,         # NOOP-check connections idle longer than this
        max_idle=120,                # drop connections idle longer than this
        max_messages_per_conn=100,   # recycle after N messages
    ):
        self.host, self.port = host, port
        self.username, self.password = username, password
        self.max_size = max_size
        self.use_starttls = use_starttls
        self.connect_timeout = connect_timeout
        self.acquire_timeout = acquire_timeout
        self.idle_check_after = idle_check_after
        self.max_idle = max_idle
        self.max_messages_per_conn = max_messages_per_conn

        self._slots = threading.BoundedSemaphore(max_size)  # hard cap
        self._idle = deque()
        self._lock = threading.Lock()
        self._closed = False

    # ---- connection lifecycle ----
    def _connect(self):
        smtp = smtplib.SMTP(self.host, self.port, timeout=self.connect_timeout)
        try:
            smtp.ehlo()
            if self.use_starttls:
                smtp.starttls(context=ssl.create_default_context())
                smtp.ehlo()
            if self.username:
                smtp.login(self.username, self.password)
        except Exception:
            self._close_smtp(smtp)
            raise
        return _PooledConn(smtp)

    @staticmethod
    def _close_smtp(smtp):
        try:
            smtp.quit()
        except Exception:
            try:
                smtp.close()
            except Exception:
                pass

    def _is_healthy(self, conn):
        now = time.monotonic()
        idle_for = now - conn.last_used
        if idle_for > self.max_idle or conn.sent >= self.max_messages_per_conn:
            return False
        if idle_for > self.idle_check_after:
            try:
                return conn.smtp.noop()[0] == 250
            except Exception:
                return False
        return True

    # ---- acquire / release ----
    def _acquire(self):
        if self._closed:
            raise RuntimeError("pool is closed")
        if not self._slots.acquire(timeout=self.acquire_timeout):
            raise PoolTimeout(f"no SMTP connection free after {self.acquire_timeout}s")
        try:
            while True:
                with self._lock:
                    conn = self._idle.pop() if self._idle else None
                if conn is None:
                    return self._connect()
                if self._is_healthy(conn):
                    return conn
                self._close_smtp(conn.smtp)
        except BaseException:
            self._slots.release()
            raise

    def _release(self, conn, discard=False):
        try:
            if discard or self._closed or conn.sent >= self.max_messages_per_conn:
                self._close_smtp(conn.smtp)
            else:
                conn.last_used = time.monotonic()
                with self._lock:
                    self._idle.append(conn)
        finally:
            self._slots.release()

    @contextmanager
    def connection(self):
        conn = self._acquire()
        discard = False
        try:
            yield conn
        except (smtplib.SMTPServerDisconnected, smtplib.SMTPConnectError, OSError):
            discard = True
            raise
        except smtplib.SMTPException:
            # state unknown after a protocol error; safest to drop the connection
            discard = True
            raise
        finally:
            self._release(conn, discard)

    # ---- public API ----
    def send(self, msg, retries=1):
        """Send an email.message.EmailMessage, retrying once on a stale connection."""
        for attempt in range(retries + 1):
            try:
                with self.connection() as conn:
                    refused = conn.smtp.send_message(msg)
                    conn.sent += 1
                    return refused
            except smtplib.SMTPServerDisconnected:
                if attempt == retries:
                    raise

    def close(self):
        self._closed = True
        with self._lock:
            conns, self._idle = list(self._idle), deque()
        for c in conns:
            self._close_smtp(c.smtp)
```

Usage:

```python
from email.message import EmailMessage

pool = SMTPPool("smtp.provider.com", 587, "user", "pass", max_size=40)

msg = EmailMessage()
msg["From"], msg["To"], msg["Subject"] = "app@example.com", "a@b.com", "Hi"
msg.set_content("Hello")
pool.send(msg)
```

**How the cap works:** every connection in use holds a semaphore permit, and a new connection is only opened when no idle one is available. Total open connections therefore never exceed 40. If all 40 are busy, callers wait up to `acquire_timeout` and then get `PoolTimeout`, so the relay should catch that and queue or retry the message instead of dropping it.

**Things to check:**
- **The cap is per process.** If you run the relay with multiple workers (gunicorn, several containers), each has its own pool, so 4 workers can open 160 connections. Either run one process or set `max_size` to `40 // workers`.
- **Check how your provider counts connections.** Some limit per IP, some per account, and some set a lower limit than you'd expect. If you still see rejections at 40, lower `max_size`. Some providers also limit messages per connection or per second, which `max_messages_per_conn` helps with but doesn't fully solve.
- **Retries on `send`:** a retry after a disconnect can occasionally duplicate a message if the server accepted it just before dropping. That's usually acceptable for transactional mail, but you can set `retries=0` if not.

I can also add a queue in front of the pool, a Go or Node version, or metrics on pool usage if you'd like.

Before the code, one concern: faster rendering probably won't fix "too many connections." That error means you're opening more simultaneous connections to the mail provider than it allows. Template rendering usually takes microseconds to milliseconds, while the SMTP handshake and send take far longer. The usual causes are:

- Opening a new SMTP connection per email instead of reusing one
- Sending bursts in parallel with no concurrency cap
- Several app instances or workers each holding their own connections

Compiled templates are still a fine startup optimization, so here's the function. But I'd also check how connections are made (details after the code).

I'm assuming Node.js with Handlebars, since you didn't mention your stack. Tell me if it's something else and I'll adapt it.

```js
// templates.js
const fs = require('fs');
const path = require('path');
const Handlebars = require('handlebars');

/**
 * Loads and compiles all .hbs templates in a directory.
 * Call once at startup; returns a map of templateName -> render function.
 */
function loadTemplates(dir) {
  const templates = {};
  const files = fs.readdirSync(dir).filter((f) => f.endsWith('.hbs'));

  if (files.length === 0) {
    throw new Error(`No .hbs templates found in ${dir}`);
  }

  for (const file of files) {
    const name = path.basename(file, '.hbs');
    const source = fs.readFileSync(path.join(dir, file), 'utf8');
    try {
      templates[name] = Handlebars.compile(source, { strict: true });
    } catch (err) {
      throw new Error(`Failed to compile template "${name}": ${err.message}`);
    }
  }

  return templates;
}

module.exports = { loadTemplates };
```

Usage:

```js
const { loadTemplates } = require('./templates');
const templates = loadTemplates(path.join(__dirname, 'emails'));

const html = templates['welcome']({ name: 'Ada' });
```

Compiling at startup means a broken template fails the deploy rather than the first email. `strict: true` also makes missing variables throw instead of rendering blank.

**Things to check for the connection errors:**

1. **Reuse connections.** With Nodemailer, use a pooled transport:
   ```js
   nodemailer.createTransport({
     host, port, auth,
     pool: true,
     maxConnections: 3,   // stay under your provider's limit
     maxMessages: 100,
   });
   ```
   Create it once at startup, not per email.
2. **Cap concurrency.** Send through a queue (BullMQ, p-limit, etc.) so bursts don't open dozens of connections at once.
3. **Count total connections across instances.** Ten workers × 5 connections each can exceed a limit that one process wouldn't.
4. **Consider the provider's HTTP API** (SendGrid, Postmark, SES, etc.) instead of SMTP. It avoids persistent-connection limits entirely.
5. **Check your provider's documented limits** and whether the errors correlate with traffic spikes.

