```typescript
import express, { Router } from "express";
import { createHash, randomBytes } from "node:crypto";
import { buildCalendar, type Booking } from "./ical";

export interface FeedStore {
  /** Look up the owner of a feed token by its SHA-256 hash (hex). */
  findUserIdByTokenHash(hash: string): Promise<string | null>;
  /** Bookings for the user whose end time is on or after `from`. */
  listBookingsForUser(userId: string, from: Date): Promise<Booking[]>;
  /** Store the new hash, replacing any previous one for this user (this revokes the old URL). */
  replaceFeedToken(userId: string, tokenHash: string): Promise<void>;
}

export interface FeedConfig {
  uidDomain: string;
  calendarName?: string;
  /** How far back to include past bookings. Default 30 days. */
  lookbackDays?: number;
}

// 32 random bytes encoded as base64url is always 43 characters.
const TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/;

function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

/** Create a token. Show `token` to the user once and store only `hash`. */
export function generateFeedToken(): { token: string; hash: string } {
  const token = randomBytes(32).toString("base64url"); // 256 bits of entropy
  return { token, hash: hashToken(token) };
}

/** Issue a new token for a user, invalidating the old one. Returns the raw token. */
export async function rotateFeedToken(store: FeedStore, userId: string): Promise<string> {
  const { token, hash } = generateFeedToken();
  await store.replaceFeedToken(userId, hash);
  return token;
}

export function createFeedRouter(store: FeedStore, config: FeedConfig): Router {
  const router = express.Router();
  const lookbackMs = (config.lookbackDays ?? 30) * 24 * 60 * 60 * 1000;

  // The .ics suffix helps some calendar clients recognize the URL as a feed.
  router.get("/calendar/:token.ics", async (req, res, next) => {
    try {
      // Applies to every response from this route, including errors.
      res.set({
        "Referrer-Policy": "no-referrer",
        "X-Robots-Tag": "noindex, nofollow",
      });

      const notFound = () => {
        res.set("Cache-Control", "no-store");
        return res.status(404).type("text/plain").send("Not found");
      };

      const { token } = req.params;
      if (!TOKEN_PATTERN.test(token)) return notFound();

      const userId = await store.findUserIdByTokenHash(hashToken(token));
      if (!userId) return notFound();

      const from = new Date(Date.now() - lookbackMs);
      const bookings = await store.listBookingsForUser(userId, from);

      const body = buildCalendar(bookings, {
        uidDomain: config.uidDomain,
        name: config.calendarName,
        cancelled: "omit",
      });

      // Hash the content so the ETag changes on any change, including removals.
      const etag = `"${createHash("sha256").update(body).digest("base64url")}"`;

      res.set({
        "Content-Type": "text/calendar; charset=utf-8",
        "Content-Disposition": 'inline; filename="bookings.ics"',
        "Cache-Control": "private, max-age=300",
        ETag: etag,
      });

      // Express compares If-None-Match against the ETag set above.
      if (req.fresh) return res.status(304).end();

      return res.status(200).send(body);
    } catch (err) {
      next(err);
    }
  });

  return router;
}
```

Mount it with `app.use(createFeedRouter(store, { uidDomain: "example.com", calendarName: "My bookings" }))`. The subscribe link you show users is `https://yourapp.com/calendar/<token>.ics`. A `webcal://` version of the same URL opens the "subscribe" flow directly in most calendar apps.

**Design choices**

- **Hashed tokens:** only the SHA-256 hash is stored, so a database leak doesn't expose working feed URLs. Plain SHA-256 is fine here because the token is 256 random bits, so there's nothing to brute-force. The tradeoff is that you can't show the user their URL again later. The UI needs a "regenerate link" button, which is what `rotateFeedToken` is for.
- **404 for everything invalid:** malformed and unknown tokens get the same response, so the endpoint reveals nothing. Malformed tokens never reach the database.
- **ETag from the content hash:** `max(updatedAt)` would miss removals, such as a cancelled booking being omitted. Calendar apps poll often, so most requests become cheap 304s.
- **`Cache-Control: private`:** this keeps shared proxies and CDNs from caching one user's feed.
- **Lookback window:** the feed only includes recent and future bookings, so it doesn't grow without bound.

**Things to do outside this code**

1. **Redact tokens in logs.** The token is in the URL path, so access logs, APM tools, and reverse proxies will record it by default. Mask `/calendar/*` paths in all of them.
2. **Rate-limit the route** per IP, for example with `express-rate-limit`. It's not strictly necessary given the token entropy, but it's cheap and limits abuse.
3. **Index `token_hash`** with a unique constraint in the database, and keep one active token per user, which is what `replaceFeedToken` assumes.
4. **Don't expect fast updates.** Google Calendar refreshes subscribed feeds every 12 to 24 hours or more, and you can't change that. Apple Calendar and Outlook are faster and respect `REFRESH-INTERVAL` and `X-PUBLISHED-TTL` properties, which you could add to the calendar header. If near-real-time matters, tell users to expect a delay with Google.

