const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB

const ALLOWED_MIME_TYPES = new Set([
  "text/csv",
  "application/csv",
  "application/vnd.ms-excel", // Windows browsers often send this for .csv
  "text/plain",
]);

const storage = multer.diskStorage({
  destination: async (_req, _file, cb) => {
    try {
      await fs.mkdir(UPLOAD_DIR, { recursive: true });
      cb(null, UPLOAD_DIR);
    } catch (err) {
      cb(err as Error, UPLOAD_DIR);
    }
  },
  // Never use the client-supplied filename on disk
  filename: (_req, _file, cb) => cb(null, `${randomUUID()}.csv`),
});

const upload = multer({
  storage,
  limits: { fileSize: MAX_FILE_SIZE, files: 1 },
  fileFilter: (_req, file, cb: FileFilterCallback) => {
    const extOk = path.extname(file.originalname).toLowerCase() === ".csv";
    const mimeOk = ALLOWED_MIME_TYPES.has(file.mimetype);
    if (!extOk || !mimeOk) {
      return cb(new Error("INVALID_FILE_TYPE"));
    }
    cb(null, true);
  },
});

// Extension and MIME type are client-controlled, so also check the content isn't binary
// (e.g. an .xlsx renamed to .csv is a zip file and contains null bytes).
async function looksLikeText(filePath: string): Promise<boolean> {
  const fh = await fs.open(filePath, "r");
  try {
    const buf = Buffer.alloc(4096);
    const { bytesRead } = await fh.read(buf, 0, buf.length, 0);
    return !buf.subarray(0, bytesRead).includes(0);
  } finally {
    await fh.close();
  }
}

router.post(
  "/lead-imports",
  requireAuth,
  requirePermission("leads:import"),
  upload.single("file"), // form field name: "file"
  async (req: Request, res: Response) => {
    const file = req.file;
    if (!file) {
      return res.status(400).json({ error: "No file uploaded. Use multipart field 'file'." });
    }

    try {
      if (file.size === 0) {
        await fs.unlink(file.path);
        return res.status(400).json({ error: "The file is empty." });
      }
      if (!(await looksLikeText(file.path))) {
        await fs.unlink(file.path);
        return res.status(400).json({ error: "File doesn't appear to be a text CSV." });
      }

      const leadImport = await db.leadImports.create({
        id: randomUUID(),
        uploadedBy: req.user.id,
        originalFilename: file.originalname,
        storagePath: file.path,
        sizeBytes: file.size,
        status: "uploaded", // uploaded -> mapped -> processing -> completed | failed
        createdAt: new Date(),
      });

      return res.status(201).json({
        id: leadImport.id,
        filename: leadImport.originalFilename,
        sizeBytes: leadImport.sizeBytes,
        status: leadImport.status,
      });
    } catch (err) {
      await fs.unlink(file.path).catch(() => {}); // don't leave orphaned files
      console.error("Lead import upload failed", err);
