export interface LeadField {
  key: string;
  label: string;
  required: boolean;
  aliases: string[]; // used to auto-suggest a mapping from header names
}

export const LEAD_FIELDS: LeadField[] = [
  { key: "email",     label: "Email",      required: true,  aliases: ["email", "emailaddress", "e-mail", "mail"] },
  { key: "firstName", label: "First name", required: false, aliases: ["firstname", "first", "givenname"] },
  { key: "lastName",  label: "Last name",  required: false, aliases: ["lastname", "last", "surname", "familyname"] },
  { key: "phone",     label: "Phone",      required: false, aliases: ["phone", "phonenumber", "mobile", "tel", "telephone"] },
  { key: "company",   label: "Company",    required: false, aliases: ["company", "companyname", "organization", "organisation", "account"] },
  { key: "jobTitle",  label: "Job title",  required: false, aliases: ["jobtitle", "title", "position", "role"] },
  { key: "source",    label: "Lead source", required: false, aliases: ["source", "leadsource", "channel"] },
  { key: "notes",     label: "Notes",      required: false, aliases: ["notes", "comments", "description"] },
];

const normalize = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");

/** Returns { fieldKey: columnIndex } for headers that clearly match a field. */
export function suggestMapping(headers: string[]): Record<string, number> {
  const result: Record<string, number> = {};
  const usedColumns = new Set<number>();
  for (const field of LEAD_FIELDS) {
    const aliases = new Set([normalize(field.key), ...field.aliases.map(normalize)]);
    const idx = headers.findIndex((h, i) => !usedColumns.has(i) && aliases.has(normalize(h)));
    if (idx !== -1) {
      result[field.key] = idx;
      usedColumns.add(idx);
    }
  }
  return result;
}
```

