    const buf = Buffer.alloc(4096);
    const { bytesRead } = await fh.read(buf, 0, buf.length, 0);
    const firstLine = buf.toString("utf8", 0, bytesRead).replace(/^\uFEFF/, "").split(/\r?\n/)[0];
    let best = ",";
    let bestCount = 0;
    for (const d of DELIMITERS) {
      const count = firstLine.split(d).length - 1;
      if (count > bestCount) { best = d; bestCount = count; }
    }
    return best;
  } finally {
    await fh.close();
  }
}

/** Reads the header row plus up to `maxRows` data rows without loading the whole file. */
async function readPreview(filePath: string, delimiter: string, maxRows: number) {
  const stream = createReadStream(filePath);
  const parser = stream.pipe(
    parse({ bom: true, delimiter, relax_column_count: true, relax_quotes: true, skip_empty_lines: true })
  );
  const rows: string[][] = [];
  try {
    for await (const record of parser) {
      rows.push(record as string[]);
      if (rows.length > maxRows) break; // header + maxRows
    }
  } finally {
    parser.destroy();
    stream.destroy();
  }
  const headers = (rows[0] ?? []).map((h) => h.trim());
  return { headers, dataRows: rows.slice(1) };
}

// Returns null for both "doesn't exist" and "belongs to someone else" so IDs can't be probed.
async function loadOwnedImport(id: string, userId: string) {
  const imp = await db.leadImports.findById(id);
  return imp && imp.uploadedBy === userId ? imp : null;
}

router.get(
  "/lead-imports/:id/preview",
  requireAuth,
  requirePermission("leads:import"),
  async (req: Request, res: Response) => {
    const imp = await loadOwnedImport(req.params.id, req.user.id);
    if (!imp) return res.status(404).json({ error: "Import not found." });

    try {
      const delimiter = await detectDelimiter(imp.storagePath);
      const { headers, dataRows } = await readPreview(imp.storagePath, delimiter, 5);
      if (headers.length === 0) {
        return res.status(422).json({ error: "Couldn't find a header row in this file." });
      }

      const columns = headers.map((header, index) => ({
        index,
        header: header || `Column ${index + 1}`,
        samples: dataRows.map((r) => r[index] ?? "").filter((v) => v.trim() !== "").slice(0, 3),
      }));

      return res.json({
        id: imp.id,
        filename: imp.originalFilename,
        columns,
        fields: LEAD_FIELDS.map(({ key, label, required }) => ({ key, label, required })),
        suggestedMapping: suggestMapping(headers), // { fieldKey: columnIndex }
        currentMapping: imp.columnMapping ?? null,
      });
    } catch (err) {
      console.error("Preview failed", err);
      return res.status(422).json({ error: "Couldn't parse this file as CSV." });
    }
  }
);

router.put(
  "/lead-imports/:id/mapping",
  requireAuth,
  requirePermission("leads:import"),
  express.json(),
  async (req: Request, res: Response) => {
    const imp = await loadOwnedImport(req.params.id, req.user.id);
    if (!imp) return res.status(404).json({ error: "Import not found." });
    if (!["uploaded", "mapped"].includes(imp.status)) {
      return res.status(409).json({ error: "This import has already started." });
    }

    const mapping = req.body?.mapping;
    if (!mapping || typeof mapping !== "object" || Array.isArray(mapping)) {
      return res.status(400).json({ error: "Body must be { mapping: { fieldKey: columnIndex } }." });
    }

    try {
      const delimiter = await detectDelimiter(imp.storagePath);
      const { headers } = await readPreview(imp.storagePath, delimiter, 0);

      const validKeys = new Set(LEAD_FIELDS.map((f) => f.key));
      const clean: Record<string, number> = {};
      const usedColumns = new Set<number>();

      for (const [key, idx] of Object.entries(mapping)) {
        if (!validKeys.has(key)) return res.status(400).json({ error: `Unknown field: ${key}` });
        if (!Number.isInteger(idx) || (idx as number) < 0 || (idx as number) >= headers.length) {
          return res.status(400).json({ error: `Invalid column for ${key}.` });
        }
        if (usedColumns.has(idx as number)) {
          return res.status(400).json({ error: "A column can only be mapped to one field." });
        }
        usedColumns.add(idx as number);
        clean[key] = idx as number;
      }

      const missing = LEAD_FIELDS.filter((f) => f.required && !(f.key in clean));
      if (missing.length) {
        return res.status(400).json({ error: `Required: ${missing.map((f) => f.label).join(", ")}` });
      }

      // Store the server-detected delimiter so the background job parses the file identically.
      await db.leadImports.update(imp.id, { columnMapping: clean, delimiter, status: "mapped" });
      return res.json({ id: imp.id, status: "mapped", mapping: clean });
    } catch (err) {
      console.error("Saving mapping failed", err);
      return res.status(500).json({ error: "Failed to save mapping." });
    }
  }
);
```

The mapping is stored as `{ fieldKey: columnIndex }`. Indexes are used rather than header names because spreadsheets often have duplicate or blank headers. The server re-validates everything because the client can't be trusted.

## 3. React component

The form has one row per CSV column, with sample data and a dropdown for the field it should import as. This matches what the user sees in their spreadsheet.

