// LeadImportMapping.tsx
import { useEffect, useMemo, useState } from "react";

interface Column { index: number; header: string; samples: string[] }
interface Field { key: string; label: string; required: boolean }
interface Preview {
  id: string;
  filename: string;
  columns: Column[];
  fields: Field[];
  suggestedMapping: Record<string, number>;
  currentMapping: Record<string, number> | null;
}

const SKIP = "";

export function LeadImportMapping({
  importId,
  onSaved,
}: {
  importId: string;
  onSaved: () => void;
}) {
  const [preview, setPreview] = useState<Preview | null>(null);
  const [assignments, setAssignments] = useState<Record<number, string>>({}); // column index -> field key
  const [loadError, setLoadError] = useState<string | null>(null);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

