    (async () => {
      try {
        const res = await fetch(`/api/lead-imports/${importId}/preview`, {
          credentials: "include",
          signal: ctrl.signal,
        });
        const body = await res.json();
        if (!res.ok) throw new Error(body.error ?? "Failed to load preview.");

        const p = body as Preview;
        // Prefer a previously saved mapping; otherwise use the auto-suggestion.
        const initial = p.currentMapping ?? p.suggestedMapping;
        const byColumn: Record<number, string> = {};
        for (const [fieldKey, colIdx] of Object.entries(initial)) byColumn[colIdx] = fieldKey;

        setPreview(p);
        setAssignments(byColumn);
      } catch (e) {
        if ((e as Error).name !== "AbortError") setLoadError((e as Error).message);
