      const mapping: Record<string, number> = {};
      for (const [colIdx, fieldKey] of Object.entries(assignments)) {
        if (fieldKey) mapping[fieldKey] = Number(colIdx);
      }
      const res = await fetch(`/api/lead-imports/${importId}/mapping`, {
        method: "PUT",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mapping }),
      });
      const body = await res.json();
      if (!res.ok) throw new Error(body.error ?? "Failed to save mapping.");
      onSaved();
