      <h2>Map columns from {preview.filename}</h2>
      <p>Choose which lead field each column should be imported as. Unmapped columns are ignored.</p>

      <table>
        <thead>
          <tr>
            <th>Column in your file</th>
            <th>Sample data</th>
            <th>Import as</th>
          </tr>
        </thead>
        <tbody>
          {preview.columns.map((col) => {
            const selected = assignments[col.index] ?? SKIP;
            return (
              <tr key={col.index}>
                <td>{col.header}</td>
                <td>{col.samples.length ? col.samples.join(" · ") : <em>(empty)</em>}</td>
                <td>
                  <select
                    aria-label={`Field for column ${col.header}`}
                    value={selected}
                    onChange={(e) => setAssignment(col.index, e.target.value)}
                  >
                    <option value={SKIP}>— Don't import —</option>
                    {preview.fields.map((f) => (
                      <option
                        key={f.key}
                        value={f.key}
                        // a field can only be used once; disable it if another column has it
                        disabled={usedFields.has(f.key) && selected !== f.key}
                      >
                        {f.label}{f.required ? " *" : ""}
                      </option>
                    ))}
                  </select>
